# -*- coding: utf-8 -*-
"""Скрытый режим обновления: отчёт кассы → запрос боту «обнови карточку товара МойСклада».

Телефон лежит на складе, его товар в МойСкладе уже есть, а данных диагностики в карточке нет
(у прежних товаров АКБ записана диапазоном, нет циклов, цвета, заключения). Касса читает
телефон по кабелю и просит бота найти товар по IMEI и обновить его доп. поля.

Здесь — только сборка запроса из отчёта, без сети и без Qt, чтобы правила проверялись
тестами. В МойСклад ходит бот Оценки (`deploy/оценка_бот/ms_card_update.py`): ключ у него.
Запрос едет тем же путём, что и запрос автоцены (касса → сервер → таблица обмена → бот), и
отличается ключом `мойсклад`.

Значения полей — те же, что касса кладёт в сделку (`ocenka.посылка`): диапазон и точный
процент батареи, циклы, память, цвет словом словаря, SIM-лоток, panic full. Отличие одно —
состояние: в сделке его выбирает сотрудник, а здесь сотрудник телефон не описывает, поэтому
состояние уходит, только когда кабель сам нашёл заменённую деталь или неродную батарею.
"""
from __future__ import annotations

from datetime import datetime

from . import ocenka

ВЕРСИЯ = 1
НАЙТИ, ЗАПИСАТЬ = "найти", "записать"


def находка(rep: dict) -> tuple:
    """Что кабель нашёл такого, что меняет состояние товара. → (phone_status | None, причина).

    Состояние меняет только заменённая деталь и неродная батарея — так обещано владельцу.
    Остальные находки (замки, паника ядра, чёрный список) в состояние не идут, но причина
    возвращается: она попадёт в «Отчёт диагностики»."""
    rep = rep or {}
    статус, причина = ocenka.переклассифицировать("норма", rep, None)
    if статус != ocenka.СТАТУС_РЕМОНТ:
        return None, ""
    деталь = (rep.get("детали_вердикт") or {}).get("итог") in ("замена", "ремонт")
    батарея = bool((rep.get("батарея") or {}).get("подделка"))
    return (ocenka.СТАТУС_РЕМОНТ if (деталь or батарея) else None), str(причина or "")


def поля(rep: dict, *, точка: str = "", ссылка_чека: str = "", когда: datetime | None = None) -> dict:
    """Что отчёт говорит про товар — словами и ключами сделки Оценки. Чего кабель не прочитал,
    того в словаре нет вовсе (None): пустым значением заполненное поле товара не затирают."""
    rep = rep or {}
    пас, бат = rep.get("паспорт") or {}, rep.get("батарея") or {}
    здоровье, циклы = бат.get("здоровье_%"), бат.get("циклы")
    статус, причина = находка(rep)
    откуда = f"Киоск {точка} от {(когда or datetime.now()):%Y-%m-%d}".replace("  ", " ")
    ссылка = str(ссылка_чека or "").strip()
    return {
        "akb": ocenka.акб_для_оценки(здоровье, циклы) if здоровье is not None else None,
        "akb_exact": здоровье,
        "akb_cycles": циклы,
        "ddr": (rep.get("память") or {}).get("объём_гб"),
        "color": ocenka.цвет_для_оценки(пас.get("цвет")),
        "sim": ocenka.sim_для_оценки(пас) if ocenka.лоток_определён(пас) else None,
        "panic_full": (rep.get("паника") or {}).get("panic_full"),
        "phone_status": статус,
        "comment_ocenka": ocenka.комментарий_оценщика(
            rep, откуда=откуда, состояние="Товар со склада" if причина else "", почему=причина),
        "ссылка_чека": ссылка if ссылка.startswith("https://") and len(ссылка) <= 300 else "",
    }


def запрос(rep: dict, код: str, *, что: str = НАЙТИ, номер: str = "", товар: str = "",
           точка: str = "", ссылка_чека: str = "") -> dict:
    """Запрос боту. `что` — «найти» (показать, что изменится) или «записать» (после
    подтверждения сотрудника; `товар` — id товара, который ему показывали). `номер` — по нему
    касса узнаёт ответ на свой последний вопрос."""
    пас = (rep or {}).get("паспорт") or {}
    имеи = [str(x).strip() for x in (пас.get("imei"), пас.get("imei2")) if str(x or "").strip()]
    return {
        "версия": ВЕРСИЯ,
        "код": str(код or ""),
        "запрос_цены": str(номер or ""),
        "точка": точка or "",
        "модель": str(пас.get("модель") or "")[:50],
        "imei": list(dict.fromkeys(имеи)),
        "мойсклад": {"что": ЗАПИСАТЬ if что == ЗАПИСАТЬ else НАЙТИ, **({"товар": str(товар)} if товар else {})},
        "поля": поля(rep, точка=точка, ссылка_чека=ссылка_чека),
    }
